    short dst[10];

    int result = copy_audio_samples(src, 5, dst, 10);

    assert(result == 5);
    for (int i = 0; i < 5; i++) {
        assert(dst[i] == src[i]);
    }
    printf("Normal copy test passed\n");
}

void test_exact_capacity() {
    short src[5] = {1, 2, 3, 4, 5};
    short dst[5];

    int result = copy_audio_samples(src, 5, dst, 5);

    assert(result == 5);
    for (int i = 0; i < 5; i++) {
        assert(dst[i] == src[i]);
    }
    printf("Exact capacity test passed\n");
}

void test_empty_copy() {
    short src[5] = {1, 2, 3, 4, 5};
    short dst[5];

    int result = copy_audio_samples(src, 0, dst, 5);

    assert(result == 0);
    printf("Empty copy test passed\n");
}

void test_large_sample_count() {
    const size_t large_count = 1000;
    short* src = malloc(large_count * sizeof(short));
    short* dst = malloc(large_count * sizeof(short));

